sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float grain;
float hash(float3 p) { p = fract(p * 0.1031); p += dot(p, p.zyx + 31.32); return fract((p.x + p.y) * p.z); }
half4 main(float2 coord) {
    half4 c = unpremul(image.eval(coord));
    float frame = mod(floor((time + 0.000999) * 30.0), 4096.0);
    half n = half(hash(float3(floor(coord / max(grain, 0.5)), frame)));
    return half4(mix(c.rgb, half3(n), half(amount)) * c.a, c.a);
}
